//! ADR-0174 P1 — the tensor `Language` fragment loads as data.
//!
//! `data/language/tensor/ast.yaml` is generated by
//! `tools/emit_tensor_language.py` (run `--check` for drift): one
//! `AstShapeDef` per `tensor.*` op — node kind, arg roles, the attrs
//! schema as data.  These tests prove the fragment *parses and merges*
//! into a `Language` and that a `Term::Op` carrying attrs round-trips
//! against the declared schema — parse/typecheck level only; binding
//! ops to host impls is a later phase.

use std::path::Path;

use handl_language::{AstShapeDef, Language, Term};
use serde_json::{Value, json};

fn fragment_path() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("data/language/tensor/ast.yaml")
}

fn load_fragment() -> Vec<AstShapeDef> {
    let text = std::fs::read_to_string(fragment_path())
        .expect("data/language/tensor/ast.yaml must exist — run tools/emit_tensor_language.py");
    serde_yaml::from_str(&text).expect("ast.yaml must deserialize as Vec<AstShapeDef>")
}

/// The declared attrs schema for `op`, read back out of the merged
/// `Language` — `payload_schema.tensor_op.attrs_schema`.
fn attrs_schema(lang: &Language, op: &str) -> Value {
    let shape = lang
        .ast
        .get_by_identity(op)
        .unwrap_or_else(|| panic!("{op} must be declared by the fragment"));
    shape
        .payload_schema
        .get("tensor_op")
        .and_then(|t| t.get("attrs_schema"))
        .cloned()
        .unwrap_or_else(|| panic!("{op} row must carry tensor_op.attrs_schema"))
}

#[test]
fn fragment_covers_the_full_op_surface() {
    let rows = load_fragment();
    // 238 = 31 handwritten seam ops + 207 ATen-ported ops
    // (src/index.hnl `op "tensor.*"` decls ∪ tool-codegen-aten --emit-spec).
    assert_eq!(rows.len(), 238, "every tensor.* op must be declared");

    let mut lang = Language::new();
    for row in &rows {
        lang.merge_ast_fragment(row.clone())
            .expect("fragment rows must merge into a Language");
    }
    for op in [
        "tensor.abs",
        "tensor.conv2d",
        "tensor.shape",
        "tensor.batch_norm_backward",
    ] {
        assert!(
            lang.ast.get_by_identity(op).is_some(),
            "{op} must land in lang.ast"
        );
    }
}

#[test]
fn attrs_schema_is_declared_as_data() {
    let mut lang = Language::new();
    for row in load_fragment() {
        lang.merge_ast_fragment(row)
            .expect("fragment rows must merge");
    }

    // tensor.concat maps mlopt's ATTR_SCHEMA: arg position 1 → `dim`,
    // `dim` is ATTR_REQUIRED on fully-attributed terms.
    let schema = attrs_schema(&lang, "tensor.concat");
    assert_eq!(schema["source"], json!("mlopt_core.attrs"));
    assert_eq!(schema["positions"], json!({"1": "dim"}));
    assert_eq!(schema["names"], json!(["arg1", "dim"]));
    assert_eq!(schema["required"], json!(["dim"]));
    assert_eq!(schema["open"], json!(true));

    // An op with no ATTR_SCHEMA entry declares honestly-open attrs.
    let open = attrs_schema(&lang, "tensor.abs");
    assert!(open["source"].is_null());
    assert_eq!(open["names"], json!([]));
    assert_eq!(open["required"], json!([]));
    assert_eq!(open["open"], json!(true));
}

#[test]
fn arity_is_declared_per_op() {
    let mut lang = Language::new();
    for row in load_fragment() {
        lang.merge_ast_fragment(row).expect("merge");
    }

    // tensor.abs: fixed arity 1 → one required arg0 role.
    let abs = lang.ast.get_by_identity("tensor.abs").unwrap();
    let children = abs.children.as_ref().expect("abs declares roles");
    assert_eq!(children.len(), 1);
    assert_eq!(children[0].role, "arg0");
    assert!(!children[0].optional);

    // tensor.constant_pad_nd: min 2 / max 3 → arg2 optional.
    let pad = lang
        .ast
        .get_by_identity("tensor.constant_pad_nd")
        .unwrap();
    let children = pad.children.as_ref().unwrap();
    assert_eq!(children.len(), 3);
    assert!(children[2].optional, "arg2 is the optional pad arg");

    // tensor.conv2d: handwritten decl → open arity, no guessed roles.
    let conv = lang.ast.get_by_identity("tensor.conv2d").unwrap();
    assert!(conv.children.is_none(), "open-arity ops stay opaque");
    assert!(
        conv.payload_schema["properties"]["children"]["minItems"].is_null(),
        "no minItems bound is declared for open arity"
    );
}

/// The fragment's declared attrs vocabulary admits exactly the spellings
/// `mlopt_core.attrs.validate_attrs` accepts: canonical names and the
/// declared `argN` aliases; undeclared extras pass (open attrs).
fn attrs_admitted(schema: &Value, attrs: &Value) -> bool {
    let names: Vec<&str> = schema["names"]
        .as_array()
        .map(|a| a.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let Some(obj) = attrs.as_object() else {
        return false;
    };
    // Every declared spelling is admitted; `open: true` admits the rest.
    obj.keys()
        .all(|k| names.contains(&k.as_str()) || schema["open"] == json!(true))
}

#[test]
fn tensor_op_term_with_attrs_round_trips() {
    let mut lang = Language::new();
    for row in load_fragment() {
        lang.merge_ast_fragment(row).expect("merge");
    }

    // A `Term::Op` for a declared tensor op carrying attrs — the
    // ADR-0173 `(op, children, attrs)` node-identity triple.
    let term = Term::op_native_attrs(
        "tensor.concat",
        vec![Term::op_native("tensor.ones", vec![])],
        json!({"dim": -1}),
    );
    let wire = serde_json::to_string(&term).expect("term serializes");
    let back: Term = serde_json::from_str(&wire).expect("term deserializes");
    assert_eq!(term, back, "attrs must survive the wire round-trip");

    // The attrs the term carries are admitted by the fragment's schema.
    let Term::Op { name, attrs, .. } = &back else {
        panic!("expected Term::Op");
    };
    assert_eq!(name, "tensor.concat");
    let attrs = attrs.as_ref().expect("attrs present after round-trip");
    let schema = attrs_schema(&lang, name);
    assert!(
        attrs_admitted(&schema, attrs),
        "attrs {attrs} must be admitted by the declared schema {schema}"
    );

    // The positional spelling mlopt also accepts round-trips too.
    let positional = Term::op_native_attrs("tensor.concat", vec![], json!({"arg1": 0}));
    let Term::Op {
        attrs: Some(a), ..
    } = positional
    else {
        panic!("expected attrs");
    };
    assert!(attrs_admitted(&attrs_schema(&lang, "tensor.concat"), &a));
}
